private void renderBeam(BlossomThorn blossomThorn, float tickDelta, PoseStack poseStack, MultiBufferSource bufferSource, RenderType type){
    float numTextures = 8.0f;
    float lifeRatio = 2.0f;
    int maxAge = 20;
    int age = maxAge - blossomThorn.lifeTicks;
    float textureProgress = Math.max(0.0F, (((age + tickDelta) * lifeRatio) / maxAge) - lifeRatio + 1);
    if (textureProgress >= 1) {
        return;
    }

    float spikeHeight = blossomThorn.height;
    float textureRatio = 22.0F / 64.0F;
    float spikeWidth = textureRatio * spikeHeight * 0.5F;
    double upProgress = (Math.sin((Math.min((age + tickDelta) / (maxAge * 0.4D), 1.0D)) * Math.PI * 0.5D) - 1.0D) * spikeHeight;
    Function<Float, Float> texTransformer = textureMultiplier(1 / numTextures, (float) (Math.floor(textureProgress * numTextures) / numTextures));
    poseStack.pushPose();
    Vec3 offset = fromLerpedPosition(blossomThorn, 0.0D, tickDelta).subtract(blossomThorn.position());
    poseStack.translate(-offset.x, upProgress - offset.y, -offset.z);
    Vec3 bottomPos = blossomThorn.randVec.add(Vec3Util.yAxis.scale(spikeHeight)).normalize();
    float n = (float) Math.acos(bottomPos.y);
    float o = (float) Math.atan2(bottomPos.z, bottomPos.x);
    float pi = (float) Math.PI;
    float rTD = 57.295776F;
    poseStack.mulPose(Axis.YP.rotationDegrees(((pi / 2.0F) - o) * rTD));
    poseStack.mulPose(Axis.XP.rotationDegrees(n * rTD));
    float q = 0.0F;
    int red = (int) (ColorUtil.WHITE.red * 255);
    int green = (int) (ColorUtil.WHITE.green * 255);
    int blue = (int) (ColorUtil.WHITE.blue * 255);
    float af = Mth.cos(q + pi) * spikeWidth;
    float ag = Mth.sin(q + pi) * spikeWidth;
    float ah = Mth.cos(q + 0.0F) * spikeWidth;
    float ai = Mth.sin(q + 0.0F) * spikeWidth;
    float aj = Mth.cos(q + (pi / 2.0F)) * spikeWidth;
    float ak = Mth.sin(q + (pi / 2.0F)) * spikeWidth;
    float al = Mth.cos(q + 4.712389F) * spikeWidth;
    float am = Mth.sin(q + 4.712389F) * spikeWidth;
    VertexConsumer vertexConsumer= bufferSource.getBuffer(type);
    PoseStack.Pose entry = poseStack.last();
    Matrix4f matrix4f = entry.pose();
    Matrix3f matrix3f = entry.normal();
    float c0 = texTransformer.apply(0.4999F);
    float c2 = texTransformer.apply(0.0F);
    float c1 = texTransformer.apply(1.0F);
    vertex(vertexConsumer, matrix4f, matrix3f, af, spikeHeight, ag, red, green, blue, c0, 0.0f);
    vertex(vertexConsumer, matrix4f, matrix3f, af, 0.0f, ag, red, green, blue, c0, 1.0f);
    vertex(vertexConsumer, matrix4f, matrix3f, ah, 0.0f, ai, red, green, blue, c2, 1.0f);
    vertex(vertexConsumer, matrix4f, matrix3f, ah, spikeHeight, ai, red, green, blue, c2, 0.0f);
    vertex(vertexConsumer, matrix4f, matrix3f, aj, spikeHeight, ak, red, green, blue, c1, 0.0f);
    vertex(vertexConsumer, matrix4f, matrix3f, aj, 0.0f, ak, red, green, blue, c1, 1.0f);
    vertex(vertexConsumer, matrix4f, matrix3f, al, 0.0f, am, red, green, blue, c0, 1.0f);
    vertex(vertexConsumer, matrix4f, matrix3f, al, spikeHeight, am, red, green, blue, c0, 0.0f);
    poseStack.popPose();
}

private static void addShieldingLineVertexPair(VertexConsumer vertexConsumer, Matrix4f matrix4f, float alpha, float ageInTicks, float baseR, float baseG, float baseB, float xDifference, float yDifference, float zDifference, float width, float secondaryWidth, float zGap, float xGap, int index, boolean otherLine) {
	float progress = (float) index / 48.0F;
	float colorBrightness = index % 2 == (otherLine ? 1 : 0) ? 0.5F : 1.0F;
	float r = baseR * colorBrightness;
	float g = baseG * colorBrightness;
	float b = baseB * colorBrightness;
	float progressedXDifference = xDifference * progress;
	float yProgress;
	if (progress < 0.1) {
		float smoothInto = progress / 0.1F;
		yProgress = (1.0F - 0.05F * smoothInto) * ((-(Mth.cos(Mth.PI * progress) - 1.0F) / 2.0F)) + 0.05F * smoothInto * Mth.sin(10.0F * Mth.PI * progress + ageInTicks);
	} else if (progress < 0.9F) {
		yProgress = 0.95F * ((-(Mth.cos(Mth.PI * progress) - 1.0F) / 2.0F)) + 0.05F * Mth.sin(10.0F * Mth.PI * progress + ageInTicks);
	} else {
		float smoothInto = (progress - 0.9F) / 0.1F;
		yProgress = (0.95F + 0.05F * smoothInto) * ((-(Mth.cos(Mth.PI * progress) - 1.0F) / 2.0F)) + (0.05F - 0.05F * smoothInto) * Mth.sin(10.0F * Mth.PI * progress + ageInTicks);
	}
	float progressedYDifference = yDifference > 0.0F ? yDifference * yProgress : yDifference - yDifference * (1.0F - yProgress);
	float progressedZDifference = zDifference * progress;
	vertexConsumer.vertex(matrix4f, progressedXDifference - zGap, progressedYDifference + secondaryWidth, progressedZDifference + xGap).color(r, g, b, alpha).uv2(15728880).endVertex();
	vertexConsumer.vertex(matrix4f, progressedXDifference + zGap, progressedYDifference + width - secondaryWidth, progressedZDifference - xGap).color(r, g, b, alpha).uv2(15728880).endVertex();
}

public static void renderBolt(PoseStack poseStack, VertexConsumer vertex, RandomSource random, Vec3 startPos, Vec3 endPos, int steps, int currentStep, boolean recurse, float r, float g, float b, int overlay, int light) {
	Vec3 direction = endPos.subtract(startPos);
	Vec3 lastPos = startPos;
	Matrix4f modelMatrix = poseStack.last().pose();

	for(int i = currentStep; i < steps; i++) {
		Vec3 randomOffset = new Vec3(random.nextGaussian(), random.nextIntBetweenInclusive(-1 / (steps * 2), 1 / (steps * 2)), random.nextGaussian());
		Vec3 nextPos = startPos.add(direction.scale((i + 1) / (float) steps)).add(randomOffset.scale(1 / 12f));

		for(int j = 0; j < 4; j++) {
			Vec3 vert1 = switch(j) {
				case 0 -> lastPos.add(0.025, 0.025, 0);
				case 1 -> lastPos.add(-0.025, 0.025, 0);
				case 2 -> lastPos.add(-0.025, -0.025, 0);
				case 3 -> lastPos.add(0.025, -0.025, 0);
				default -> lastPos;
			};
			Vec3 vert2 = switch(j) {
				case 0 -> lastPos.add(-0.025, 0.025, 0);
				case 1 -> lastPos.add(-0.025, -0.025, 0);
				case 2 -> lastPos.add(0.025, -0.025, 0);
				case 3 -> lastPos.add(0.025, 0.025, 0);
				default -> lastPos;
			};
			Vec3 vert3 = switch(j) {
				case 0 -> nextPos.add(0.025, 0.025, 0);
				case 1 -> nextPos.add(-0.025, 0.025, 0);
				case 2 -> nextPos.add(-0.025, -0.025, 0);
				case 3 -> nextPos.add(0.025, -0.025, 0);
				default -> nextPos;
			};
			Vec3 vert4 = switch(j) {
				case 0 -> nextPos.add(-0.025, 0.025, 0);
				case 1 -> nextPos.add(-0.025, -0.025, 0);
				case 2 -> nextPos.add(0.025, -0.025, 0);
				case 3 -> nextPos.add(0.025, 0.025, 0);
				default -> nextPos;
			};
			Vec3 normal = vert2.subtract(vert1).cross(vert3.subtract(vert1));

			vertex.addVertex(modelMatrix, (float) vert2.x(), (float) vert2.y(), (float) vert2.z()).setColor(r, g, b, 0.6f).setUv(0, 0).setOverlay(overlay).setLight(light).setNormal(poseStack.last(), (float) normal.x(), (float) normal.y(), (float) normal.z());
			vertex.addVertex(modelMatrix, (float) vert4.x(), (float) vert4.y(), (float) vert4.z()).setColor(r, g, b, 0.6f).setUv(0, 0).setOverlay(overlay).setLight(light).setNormal(poseStack.last(), (float) normal.x(), (float) normal.y(), (float) normal.z());
			vertex.addVertex(modelMatrix, (float) vert3.x(), (float) vert3.y(), (float) vert3.z()).setColor(r, g, b, 0.6f).setUv(0, 0).setOverlay(overlay).setLight(light).setNormal(poseStack.last(), (float) normal.x(), (float) normal.y(), (float) normal.z());
			vertex.addVertex(modelMatrix, (float) vert1.x(), (float) vert1.y(), (float) vert1.z()).setColor(r, g, b, 0.6f).setUv(0, 0).setOverlay(overlay).setLight(light).setNormal(poseStack.last(), (float) normal.x(), (float) normal.y(), (float) normal.z());
		}

		while(recurse && random.nextFloat() < 0.2f) {
			Vec3 randomOffset1 = new Vec3(random.nextGaussian(), random.nextGaussian(), random.nextGaussian());
			renderBolt(poseStack, vertex, random, lastPos, endPos.add(randomOffset1.scale(Math.min(random.nextFloat(), 0.6f))), steps, i + 1, false, r, g, b, overlay, light);
		}

		lastPos = nextPos;
	}
}

private Pair<BoltQuads, QuadCache> createQuads(@Nullable QuadCache cache, Vec3 startPos, Vec3 end, float size) {
    Vec3 diff = end.subtract(startPos);
    Vec3 rightAdd = diff.cross(new Vec3(0.5, 0.5, 0.5)).normalize().scale(size);
    Vec3 backAdd = diff.cross(rightAdd).normalize().scale(size);
    Vec3 rightAddSplit = rightAdd.scale(0.5F);

    Vec3 start = cache != null ? cache.prevEnd() : startPos;
    Vec3 startRight = cache != null ? cache.prevEndRight() : start.add(rightAdd);
    Vec3 startBack = cache != null ? cache.prevEndBack() : start.add(rightAddSplit).add(backAdd);
    Vec3 endRight = end.add(rightAdd);
    Vec3 endBack = end.add(rightAddSplit).add(backAdd);

    BoltQuads quads = new BoltQuads();
    quads.addQuad(start, end, endRight, startRight);
    quads.addQuad(startRight, endRight, end, start);

    quads.addQuad(startRight, endRight, endBack, startBack);
    quads.addQuad(startBack, endBack, endRight, startRight);

    return Pair.of(quads, new QuadCache(end, endRight, endBack));
}

@Override
public void tick() {
    if (particle == null) {
        this.remove();
        return;
    }
    Vec3 oldpos = particle.getPos();
    if (!particle.isAlive()) {
        this.remove();
        return;
    }
    cycle = cycle + (float) speed;
    while (cycle >= 360) {
        cycle -= 360;
    }
    Vec3 pos = calculatePos();
    particle.setPos(pos.x, pos.y, pos.z);
    ((ParticleAccessor) particle).irons_spellbooks$xo(oldpos.x);
    ((ParticleAccessor) particle).irons_spellbooks$yo(oldpos.y);
    ((ParticleAccessor) particle).irons_spellbooks$zo(oldpos.z);
    height += dHeight;
    width += dWidth;
    speed += dSpeed;
    move(xd, yd, zd);
}

    private void renderLightningPass(VertexConsumer consumer, PoseStack poseStack, float partialTick, float tubeWidth, float chanceToBranch) {
        RandomSource randomSource = RandomSource.create((age + lifetime) * 3456798L);
        Vec3 start = Vec3.ZERO;
        Vec3 end = destination.subtract(this.getPos()); // local space
        double distance = end.length();
        int segments = (int) (distance / 4 + randomSource.nextIntBetweenInclusive(1, 3));
        double distancePerSegment = distance / segments;
        Vec3 direction = end.normalize();
        for (int i = 0; i < segments; i++) {
            Vec3 wiggle = randomOffset(randomSource, .2f);
            Vec3 segmentEnd = start.add(direction.scale(distancePerSegment)).add(wiggle);

            drawLightningBeam(consumer, poseStack, partialTick, start, segmentEnd, tubeWidth, chanceToBranch, randomSource);

            start = segmentEnd;
//            end = end.subtract(wiggle).add(end);
        }
    }
